 let V=0,over=0,pour=0;const pf=v=>{const nb=.1*v,tot=aV+v;if(!L.weak){const n=nb-na;return Math.abs(n)<1e-9?7:n<0?-Math.log10(-n/tot):14+Math.log10(n/tot)}if(v<.001)return -Math.log10(Math.sqrt(Ka*Ca));if(nb<na-1e-9)return pKa+Math.log10(nb/(na-nb));if(Math.abs(nb-na)<1e-9)return 14+.5*Math.log10(1e-14/Ka*cs);return 14+Math.log10((nb-na)/tot)};
 const check=()=>{if(over)return;over=1;pour=0;const p=pf(V);if(Math.abs(p-target)<=L.tol){end(1);const ca=.1*V/aV;msg(`🏆 ممتاز! أضفت ${V.toFixed(1)} مل وكان pH = ${p.toFixed(2)}. عند التعادل n(H⁺) = n(OH⁻)، فتركيز الحمض Ca = Cb·Vb/Va = 0.1×${V.toFixed(1)}/${aV} = ${ca.toFixed(3)} M.${L.weak?' ولأن الملح الناتج يتميّأ يكون pH عند التعادل أكبر من 7.':''} ${q_star('titr',lv,Math.abs(p-target)<=L.tol/2?3:2)}`);btns([[lv<TL.length-1?'المرحلة التالية ▶':'من البداية',()=>titr(lv<TL.length-1?lv+1:0)]])}else{end(0);msg(`😢 توقفت عند pH = ${p.toFixed(1)} (${p<target?'قبل التعادل — تحتاج مزيدًا من القاعدة':'بعد التعادل — زدت القاعدة'}). المطلوب pH ≈ ${target.toFixed(1)}.`);btns([['حاول مجددًا',()=>titr(lv)]])}};
